"""What the instruction manuals say about each instruction's operands.

Generated data: operand positions and type codes only, no manual text.

Two things are read per instruction. The ST signature line
("ENO:=MC(EN,N,d);") gives which operands that one instruction takes --
necessary because a page often documents several instructions together, and
MC(EN,N,d) and MCR(EN,N) do not take the same ones. The operand table gives the
ladder order and names each operand. ST puts the output last and ladder does
not, so the order comes from the operand table only.

Source: the ST signature and operand tables ("内容，範囲，データ型") of
  - MELSEC iQ-R Programming Manual (CPU Module Instructions, Standard
    Functions/Function Blocks)                        SH-081226-AF
  - MELSEC iQ-R Programming Manual (Module Dedicated Instructions)
    ..............................................    SH-081975-R
  - MELSEC iQ-R Programming Manual (Process Control Function Blocks/
    Instructions)                                     SH-081748-O
  - MELSEC iQ-R Ethernet User's Manual (Application)  SH-081253-AI

Do not hand-edit. Regenerate from the manual tables when a revision changes an
instruction.
"""

from __future__ import annotations

# --- Write targets ----------------------------------------------------------
#
# The manuals name every operand: (d), (d1), (d2) are the destinations, (s*)
# the sources, (n*) counts, (U) the module head I/O number. The destinations
# are what this table records. EN/ENO are FBD/LD-only pins and are not ladder
# operands, so they are excluded from the operand count and from the indices.
#
# Keyed by operand count because several instructions take a different number
# of operands with different destinations -- WAND with 2 operands writes its
# second, with 3 operands its third.

