# --- Operand data types -----------------------------------------------------
#
# Width and signedness per operand, from the same tables. The manuals give this
# per operand rather than per instruction: BMOV is a 16-bit move but its (n) is
# a count, and DB* takes two BCD8 operands and writes BCD16. Where a page
# documents a signed and an unsigned form together, the row naming the variant
# ("BKCMP□(P)" against "BKCMP□(P)_U") decides which applies.
#
# Codes: bit, word (16-bit, signedness unstated), int16/uint16, int32/uint32,
# real32 (single precision, 2 words), real64 (double precision, 4 words),
# bcd4/bcd8/bcd16, string, wstring, device, dword. An operand whose manual
# entry lists several alternatives is left blank rather than guessed at.

