def manual_allowed_devices(opcode: str, operand: str) -> tuple[str, ...] | None:
    """Device types this operand accepts, or None when the manuals do not say."""
    entry = MANUAL_ALLOWED_DEVICES.get(opcode)
    if entry is None:
        return None
    return entry.get(operand)


