def manual_operand_names(opcode: str, argc: int) -> tuple[str, ...] | None:
    """Operand names in ladder order, or None when the manuals do not say."""
    entry = MANUAL_OPERAND_NAMES.get(opcode)
    if entry is None:
        return None
    return entry.get(argc)
